  function cartTotal() { return state.editorLines.reduce((sum,line)=>sum + number(line.qty)*number(line.unit_price) + (line.extras||[]).reduce((extraSum,extra)=>extraSum + number(extra.qty)*number(extra.unit_price),0),0); }
