  async function saveReservation() { const payload=editorPayload();if(!payload.outlet_id)throw new Error('Outlet reservasi wajib dipilih.');if(!payload.customer_name.trim())throw new Error('Nama customer wajib diisi.');if(!payload.reservation_at)throw new Error('Tanggal dan jam reservasi wajib diisi.');if(!payload.lines.length)throw new Error('Pilih minimal satu produk.');if(payload.deposit.amount>0 && !payload.deposit.payment_method_id)throw new Error('Pilih metode pembayaran untuk DP.');if(payload.deposit.amount>cartTotal()+.009)throw new Error('DP tidak boleh melebihi total tagihan.');const data=await postPosTransactionJson(urls.save,payload);notify(`Reservasi ${data.reservation_no||''} berhasil disimpan.`, 'success');editorModal && editorModal.hide();await loadRows();return data; }
